Tactic Notation "in_seed" hyp(MU) constr(A) constr(S) "by" tactic3(tac) :=
  lazymatch type of MU with munch ?W _ _ => let K := fresh "INc" in assert (K : chunk_in W A S) by (unfold chunk_in; cbn [inside]; tac) end.
Tactic Notation "in_noseed" hyp(MU) constr(A) constr(S) :=
  lazymatch type of MU with munch ?W _ _ => let K := fresh "INn" in pose proof (I : chunk_noin W A S) as K end.

Lemma land64_mod : forall x, Z.land x 18446744073709551615 = x mod 2^64.
Proof. intros x. change 18446744073709551615 with (Z.ones 64). rewrite Z.land_ones by lia. reflexivity. Qed.
Lemma land_fb0_2 : forall f, 0 <= f -> Z.land (f mod 256) 2 = if Z.testbit f 1 then 2 else 0.
Proof.
  intros f Hf. change 2 with (2^1) at 1. rewrite land_pow2_testbit by lia.
  change 256 with (2^8). rewrite <- Z.land_ones by lia. rewrite Z.land_spec, Z.ones_spec_low by lia.
  rewrite Bool.andb_true_r. reflexivity.
Qed.

