Definition bp_ec_stmt (pc cont : Z) : Prop :=
  forall (rax : word) (spa : Z) (gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 : word) (E P ff n : Z)
         (t3 t4 t5 t6 : word) (F : bvmap 5 word) fc (m : mem) (p0 p1 p : Z) (j0 j128 j152 : list byte) (E1 : ecv),
  rw_cells bsegs m spa (bp_locals E P p0 ff j0 j128 j152 p) ->
  rw_cells bsegs m E (ErrCodeCells E1) -> ec_ok E1 -> (E1 = EC_clear \/ http_fail E1) ->
  accessible m E 24 -> E mod 8 = 0 -> mem_inv bsegs m ->
  evt bsegs (fun ms' => exists a0' a1',
                 (E1 = EC_clear /\ ms' = bp_ms cont rax spa gp tp t0 t1 t2 sp0 a0' a1' a2 a3 a4 a5 a6 a7 E P ff p1 n t3 t4 t5 t6 F fc m)
              \/ (http_fail E1 /\ ms' = bp_ms BP_DONE rax spa gp tp t0 t1 t2 sp0 a0' a1' a2 a3 a4 a5 a6 a7 E P ff p1 n t3 t4 t5 t6 F fc m))
    (bp_ms pc rax spa gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 E P ff p1 n t3 t4 t5 t6 F fc m).

Local Ltac ec_prologue :=
  intros until E1; intros LOC EC EOK ECF ACE EAL MI;
  lazymatch goal with ACEx : accessible ?mc ?Ev 24, EALx : ?Ev mod 8 = 0, LOCx : rw_cells _ ?mc ?spav (bp_locals _ _ _ _ _ _ _ _), ECx : rw_cells _ ?mc ?Ev (ErrCodeCells ?E1v) |- _ =>
    let LB := fresh "LB" in let EB := fresh "EB" in
    pose proof (rw_cells_bound _ _ _ _ LOCx) as LB; cbn [cells_size csize Nat.add bp_locals length] in LB;
    pose proof (rw_cells_bound _ _ _ _ ECx) as EB; cbn [cells_size csize Nat.add ErrCodeCells length] in EB;
    destruct EOK as (EV1 & EV2 & EV3 & EV4);
    unfold bp_ms, BP_DONE; unfold bp_locals, shw, ErrCodeCells, BP_JT in *; unfold wz in *;
    (* [comment removed for export] *)
    let RD := fresh "RD" in
    pose proof (accessible_read0_sr mc Ev 24 (Ev + 16) ACEx ltac:(clear; lia) ltac:(clear - EALx; Z.div_mod_to_equations; lia) ltac:(clear; lia)) as RD;
    step; clear RD; sh0_lit; shchk_br;
    (* [comment removed for export] *)
    step; step
  end.

Local Ltac ec_cases :=
  let KF := fresh "KF" in
  lazymatch goal with ECF : ?E1v = EC_clear \/ http_fail ?E1v, EV4 : ec_flags ?E1v <> 1 |- _ =>
  destruct ECF as [->|HF];
  [ (* [comment removed for export] *)
    cbn [ec_flags ec_val ec_cat EC_clear] in *;
    step; if_cases KF; zify_cond KF; rewrite ?unsigned_lit in KF by lia; cbn in KF;
    [ apply evt_done; eexists _, _; left; split; reflexivity | exfalso; clear - KF; lia ]
  | (* [comment removed for export] *)
    pose proof HF as (HC & HFd & _ & HF2 & HV); unfold ec_failed in HFd;
    step; if_cases KF; zify_cond KF; rewrite ?unsigned_lit in KF by lia; rewrite (land1_odd (ec_flags E1v)) in KF by (first [exact HFd| lia]);
    [ exfalso; clear - KF; lia | clear KF ];
    step; step; if_cases KF; zify_cond KF; rewrite ?unsigned_lit in KF by lia;
    [ apply evt_done; eexists _, _; right; split; [exact HF| reflexivity] | exfalso; clear - KF EV4; lia ] ]
