(* [comment removed for export] *)
Lemma bp_tail : forall (rax : word) (spa : Z) (gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 : word) (E P ff n : Z)
    (t3 t4 t5 t6 : word) (F : bvmap 5 word) fc (m : mem) (c : pcore) (pad7 pad2 j0 j128 j152 : list byte) (p0 p1 p : Z),
  rw_cells bsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells bsegs m spa (bp_locals E P p0 ff j0 j128 j152 p) ->
  accessible m P 344 -> P mod 8 = 0 -> mem_inv bsegs m ->
  0 <= p0 -> p0 <= p -> p <= p1 -> p1 < 2^64 ->
  evt bsegs (fun ms' => exists a0' a1' a2',
                 ms' = bp_ms BP_DONE rax spa gp tp t0 t1 t2 sp0 a0' a1' a2' a3 a4 a5 a6 a7 E P ff p1 n t3 t4 t5 t6 F fc m
              \/ (ms' = bp_ms BP_DISP rax spa gp tp t0 t1 t2 sp0 a0' a1' a2' a3 a4 a5 a6 a7 E P ff p1 (p1 - p) t3 t4 t5 t6 F fc m
                  /\ p < p1 /\ pc_state c <> 11 /\ Z.testbit (pc_f c) 1 = true))      (* [comment removed for export] *)
