Scheme kc__4 := Elimination for Corelib.Init.Logic.ex Sort Prop.

(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma bp_done : forall (Q : machine_state -> Prop) (m : mem) (sp : word) (spa lo shi : Z) (LF : list fframe) (ff fp : Z)
    (rax gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
    (E P n p0 p1 p : Z) (j0 j128 j152 ja j48 jb j80 jc j112 : list byte) (gap : list cell) (sa sb sc : Z) (F : bvmap 5 word) fc,
  rw_cells bsegs m spa (bp_locals E P p0 ff j0 j128 j152 p) ->
  rw_cells bsegs m (spa + 184) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 184) ->
  rw_cells bsegs m (bv_unsigned sp + -104) (bp_saves s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav) ->
  (spa = bv_unsigned sp + -288 \/ spa = bv_unsigned sp + -304) ->
  stk bsegs m lo spa -> aceil <= lo -> lo <= spa ->
  rw_cells bsegs m ff (bp_ffr spa fp ja j48 jb j80 jc j112) ->
  rw_cells bsegs m (sh ff) (bp_sh sa sb sc) ->
  rw_cells bsegs m fp [C1 (b8 1)] ->
  fresh_frame H LF 1 ff fp -> as_RFS H ((1, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi -> mem_inv bsegs m ->
  0 <= p0 -> p0 <= p < 2^64 ->
  (forall m' j5,
     munch [(ff, ff + 8); (sh ff, sh ff + 16); (fp, fp + 1)]%Z m m' -> wmono bsegs m m' -> mem_inv bsegs m' ->
     as_RFS H LF m' -> ACONST m' -> stack0 m' lo shi ->
     stk bsegs m' lo (bv_unsigned sp) ->
     rw_cells bsegs m' ff (C8 (wz BP_MAGIC2) :: tl (bp_ffr spa fp ja j48 jb j80 jc j112)) ->
     rw_cells bsegs m' (sh ff) [CB 16 j5] ->
     rw_cells bsegs m' fp [C1 (b8 0)] ->
     Q (MS (mkR rav sp gp tp t0 t1 t2 s0v s1v (wz (p - p0)) (wz fp) (wz ff) (wz ff) a4 a5 a6 a7
                s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6)
           F (ret_pc rav) fc None m' (seg_rom bsegs))) ->
